"""Read the authors' released result files and compare them with our numbers.

The files shipped in the repository are for the *10x more epochs than Table 1*
setting (suffix ``100_xepochs``, i.e. 40 * 100 = 4000 epochs).  They are used
here as an external anchor computed by the authors' own code; nothing is typed
in by hand.
"""

from __future__ import annotations

import math

import numpy as np

import data_utils as du


def read_column(dataset: str, name: str, tag: str = "100_xepochs_1_hidden_layers"):
    """Read a released per-split result file (one number per line)."""
    path = du.results_path(dataset) / f"{name}_{tag}.txt"
    if not path.exists():
        return None
    values = []
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            values.append(float(line))
        except ValueError:
            continue
    return np.array(values, dtype=np.float64)


def released_summary(dataset: str, tag: str = "100_xepochs_1_hidden_layers") -> dict:
    rmse = read_column(dataset, "test_MC_rmse", tag)
    ll = read_column(dataset, "test_ll", tag)
    tau = read_column(dataset, "test_tau", tag)
    out = {"tag": tag}
    if rmse is not None and rmse.size:
        out["n_splits"] = int(rmse.size)
        out["mean_rmse"] = float(np.mean(rmse))
        out["std_error_rmse"] = float(np.std(rmse) / math.sqrt(rmse.size))
        out["per_split_rmse"] = [float(v) for v in rmse]
    if ll is not None and ll.size:
        out["mean_ll"] = float(np.mean(ll))
        out["std_error_ll"] = float(np.std(ll) / math.sqrt(ll.size))
    if tau is not None and tau.size:
        out["selected_taus"] = [float(v) for v in tau]
    return out


def main():
    import config

    for dataset in ["Boston Housing", "Yacht Hydrodynamics", "Power Plant"]:
        s = released_summary(dataset)
        if "mean_rmse" in s:
            print(f"{dataset}: released 100x-epoch grid search -> "
                  f"MC RMSE {s['mean_rmse']:.4f} +- {s['std_error_rmse']:.4f} "
                  f"(n={s['n_splits']}), LL {s.get('mean_ll', float('nan')):.4f}")


if __name__ == "__main__":
    main()
